<script setup lang="ts">
import { ArrowRight, Check, Clock3, RefreshCw, ShieldCheck, TriangleAlert } from '@lucide/vue'
import { SALON_TIMEZONE, formatXof } from '~~/shared/constants/business'
import type { BookingGuestStatus } from '~~/shared/types/booking'
const route=useRoute(),booking=ref<BookingGuestStatus|null>(null),loading=ref(true),errorMessage=ref(''),refreshing=ref(false),checkedAt=ref<Date|null>(null),attempts=ref(0)
const manualReviewPayments=computed(()=>booking.value?.payments.filter((payment)=>payment.status==='paid_manual_review')??[])
const manualReviewAmountXof=computed(()=>manualReviewPayments.value.reduce((sum,payment)=>sum+payment.amountXof,0))
const statusLabel=computed(()=>manualReviewAmountXof.value>0?'Paiement reçu, rendez-vous non confirmé':booking.value?.status==='confirmed'?'Rendez-vous confirmé':booking.value?.status==='pending_payment'?'En attente du paiement rapproché':booking.value?.status==='cancelled'?'Rendez-vous annulé':booking.value?.status==='expired'?'Retenue expirée':booking.value?.status==='payment_failed'?'Paiement non confirmé':'Demande de réservation enregistrée')
const statusDetail=computed(()=>manualReviewAmountXof.value>0?'Le paiement est vérifié auprès de FedaPay, mais le rendez-vous n’est pas confirmé. Ne payez pas une seconde fois : contactez le salon pour convenir d’une nouvelle date ou du traitement de la transaction. Aucun remboursement automatique n’a été lancé.':booking.value?.status==='confirmed'?'Le salon a confirmé votre rendez-vous.':booking.value?.status==='pending_payment'?'Le prestataire de paiement vérifie encore la transaction. Ne payez pas une seconde fois avant d’avoir vérifié son statut.':booking.value?.status==='expired'?'La retenue de créneau a expiré. Aucun rendez-vous n’est confirmé.':'Cet écran vérifie l’état enregistré côté serveur; retour navigateur et capture d’écran ne valent pas confirmation de paiement.')
const serviceSummary=computed(()=>booking.value?.services.map((item)=>item.name).join(' · ')||'')
function localDate(value:string){return new Intl.DateTimeFormat('fr-BJ',{timeZone:SALON_TIMEZONE,dateStyle:'full',timeStyle:'short'}).format(new Date(value))}
async function refreshStatus(){errorMessage.value='';const token=import.meta.client?sessionStorage.getItem('onglerie-guest-token'):null,id=import.meta.client?sessionStorage.getItem('onglerie-booking-id'):null;if(!token||!id){errorMessage.value='Aucun accès de réservation invité n’est disponible dans ce navigateur. Ouvrez le lien de suivi sur l’appareil utilisé lors de la réservation ou connectez-vous à votre compte.';loading.value=false;return}if(typeof route.query.booking==='string'&&route.query.booking!==id){errorMessage.value='Le retour de paiement ne correspond pas à la réservation conservée dans ce navigateur.';loading.value=false;return}refreshing.value=true;try{const result=await $fetch<{booking:BookingGuestStatus}>('/api/bookings/status',{method:'POST',body:{token}});booking.value=result.booking;checkedAt.value=new Date()}catch(error){errorMessage.value=(error as{data?:{statusMessage?:string}})?.data?.statusMessage||'Le statut ne peut pas être vérifié maintenant. Cela ne signifie pas que le paiement ou le rendez-vous est confirmé.'}finally{refreshing.value=false;loading.value=false}}
onMounted(async()=>{await refreshStatus();while(booking.value?.status==='pending_payment'&&attempts.value<4){attempts.value++;await new Promise((resolve)=>setTimeout(resolve,3000));await refreshStatus()}})
useSeoMeta({title:'Suivi de réservation',description:'Consultez l’état réel de votre rendez-vous.',robots:'noindex,nofollow'})
</script>
<template>
  <div class="container-page confirmation-page"><section class="confirmation-card surface-card">
    <div class="confirmation-symbol" :class="{'is-confirmed':booking?.status==='confirmed','is-pending':booking?.status==='pending_payment'}"><Check v-if="booking?.status==='confirmed'" :size="28"/><Clock3 v-else-if="booking?.status==='pending_payment'" :size="27"/><TriangleAlert v-else :size="25"/></div>
    <span class="section-kicker">Suivi sécurisé</span><h1 class="display">{{loading?'Vérification en cours…':statusLabel+'.'}}</h1><p class="confirmation-copy">{{loading?'Nous vérifions l’état enregistré pour votre réservation.':statusDetail}}</p><p v-if="errorMessage" class="confirmation-error" role="alert">{{errorMessage}}</p>
    <template v-if="booking"><div class="booking-facts"><p><span>Référence</span><strong>{{booking.reference}}</strong></p><p><span>Rendez-vous</span><strong>{{localDate(booking.startsAt)}}</strong></p><p><span>Professionnelle</span><strong>{{booking.staffName}}</strong></p><p><span>Prestations</span><strong>{{serviceSummary}}</strong></p><p><span>Total</span><strong>{{formatXof(booking.totalXof)}}</strong></p><p><span>Acompte demandé</span><strong>{{formatXof(booking.depositDueXof)}}</strong></p><p v-if="manualReviewAmountXof>0"><span>Paiement reçu à vérifier</span><strong>{{formatXof(manualReviewAmountXof)}}</strong></p><p><span>Rapproché côté serveur</span><strong>{{formatXof(booking.amountPaidXof)}}</strong></p><p><span>Solde estimé</span><strong>{{formatXof(booking.remainingXof)}}</strong></p></div>
      <p class="secure-note"><ShieldCheck :size="15"/> Un rendez-vous n’est confirmé qu’après vérification par le serveur du paiement, du montant et de la devise.</p><p v-if="checkedAt" class="last-checked">Dernière vérification · {{checkedAt.toLocaleTimeString('fr-BJ')}}</p><p v-if="booking.salon.phone||booking.salon.whatsapp||booking.salon.email" class="contact-note">Pour toute question sur une transaction en attente, contactez le salon par les coordonnées affichées sur son site.</p>
    </template>
    <div class="confirmation-actions"><button class="btn btn-secondary" :disabled="refreshing" @click="refreshStatus"><RefreshCw :size="14"/> {{refreshing?'Vérification…':'Actualiser le statut'}}</button><NuxtLink class="btn btn-primary" to="/mon-compte/rendez-vous">Mes rendez-vous <ArrowRight :size="15"/></NuxtLink><NuxtLink class="btn btn-secondary" to="/reservation/recuperer">Retrouver une réservation invitée</NuxtLink></div>
  </section><p class="confirmation-footer">Si la page de paiement a été fermée, ce suivi ne débite rien. En cas de doute, ne recommencez pas avant d’avoir vérifié auprès du fournisseur ou du salon.</p></div>
</template>
<style scoped>.confirmation-page{display:grid;justify-items:center;padding-block:clamp(3rem,9vw,7rem)}.confirmation-card{width:min(100%,720px);padding:clamp(1.4rem,5vw,3rem);border-radius:1.1rem;text-align:center}.confirmation-symbol{display:grid;width:58px;height:58px;place-items:center;margin:0 auto 1rem;border:1px solid #d8cbc4;border-radius:50%;color:#867670;background:#fbf7f3}.confirmation-symbol.is-confirmed{border-color:#9ac8ab;color:#357451;background:#f3faf4}.confirmation-symbol.is-pending{border-color:#d9c9a5;color:#806127;background:#fcf8ec}.confirmation-card h1{margin:.55rem 0;font-size:clamp(2rem,6vw,3.6rem)}.confirmation-copy{max-width:560px;margin:.4rem auto 1.2rem;color:#756761;font-size:.78rem;line-height:1.7}.confirmation-error{border:1px solid #e6cfca;border-radius:.6rem;padding:.7rem;color:#883e42;background:#fff6f4;font-size:.7rem}.booking-facts{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem;margin:1.1rem 0;text-align:left}.booking-facts p{display:grid;gap:.22rem;margin:0;padding:.7rem;border-radius:.5rem;background:#faf6f1}.booking-facts span,.last-checked{color:#897c73;font-size:.58rem}.booking-facts strong{color:#3e3330;font-size:.7rem;font-weight:600;line-height:1.5}.secure-note{display:flex;justify-content:center;align-items:center;gap:.4rem;color:#6f544e;font-size:.63rem;line-height:1.6}.confirmation-actions{display:flex;justify-content:center;gap:.55rem;flex-wrap:wrap;margin-top:1rem}.confirmation-footer{max-width:650px;margin:1rem auto 0;color:#857970;font-size:.62rem;text-align:center;line-height:1.7}.contact-note{color:#735348;font-size:.64rem}@media(max-width:560px){.booking-facts{grid-template-columns:1fr}.confirmation-actions{align-items:stretch;flex-direction:column}.confirmation-actions>*{justify-content:center}}</style>
